if os.path.exists(cp):
 q=sqlite3.connect(cp); q.row_factory=sqlite3.Row; out[\"cache_integrity\"]=q.execute(\"pragma integrity_check\").fetchone()[0]; out[\"cache_migrations\"]=[list(x) for x in q.execute(\"select version,name from observation_schema order by version\")]; out[\"cache_stats\"]=dict(q.execute(\"select count(*) total,coalesce(sum(content_completeness=\\\"COMPLETE\\\"),0) complete from crawl_observations\").fetchone()); q.close()
